            config->force_term = 1;
        } else if (strcmp(argv[i], "-l") == 0) {
            config->linux_mode = 1;
        } else if (strcmp(argv[i], "-L") == 0) {
            config->lock = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            config->old_scroll = 1;
        } else if (strcmp(argv[i], "-n") == 0) {
            config->no_bold = 1;
