    if (config->tty_fd < 0) {
        max_fd = STDIN_FILENO;
    }

    printf("DEBUG: Starting run_loop, max_fd=%d, tty_fd=%d\n", max_fd, config->tty_fd);
    fflush(stdout);

    int iterations = 0;
    while (!config->quit && iterations < 10) {
        FD_ZERO(&readfds);
        if (config->tty_fd >= 0) {
            FD_SET(config->tty_fd, &readfds);
        }
        FD_SET(STDIN_FILENO, &readfds);

        tv.tv_sec = config->update_delay;
        tv.tv_usec = 0;

        printf("DEBUG: Calling select, max_fd=%d\n", max_fd);
        fflush(stdout);

        int ret = select(max_fd + 1, &readfds, NULL, NULL, &tv);
        printf("DEBUG: select returned %d\n", ret);
        fflush(stdout);

        if (ret > 0) {
            if (config->tty_fd >= 0 && FD_ISSET(config->tty_fd, &readfds)) {
                char buf[1];
                read(config->tty_fd, buf, 1);
            }
            if (FD_ISSET(STDIN_FILENO, &readfds)) {
                char buf[1];
                read(STDIN_FILENO, buf, 1);
            }
        }

