+#include "core.h"
+
+int main(int argc, char **argv) {
+    cmatrix_config config;
+    init_config(&config);
+    
+    if (parse_args(argc, argv, &config) == 0) {
+        if (config.help) {
+            print_usage(argv[0]);
+            return 0;
+        }
+        if (config.version) {
+            print_version();
+            return 0;
+        }
+        
+        if (setup_terminal(&config) != 0) {
+            fprintf(stderr, "Error: Failed to setup terminal\n");
+            return 1;
+        }
+        
+        generate_matrix(&config);
+        run_loop(&config);
+        
+        restore_terminal(&config);
+        free_config(&config);
+    }
+    
+    return 0;
+}
